{
  "items": [
    {
      "name": "Finset.sum_Ico_eq_sum_range",
      "module_name": "Mathlib.Algebra.BigOperators.Intervals",
      "kind": "theorem",
      "type": "∀ {M : Type u_3} [inst : AddCommMonoid M] (f : ℕ → M) (m n : ℕ),\n  ∑ k ∈ Finset.Ico m n, f k = ∑ k ∈ Finset.range (n - m), f (m + k)"
    },
    {
      "name": "Finset.sum_range_le_sum",
      "module_name": "Mathlib.Algebra.Order.Group.Int.Sum",
      "kind": "theorem",
      "type": "∀ {s : Finset ℤ} {c : ℤ}, (∀ x ∈ s, c ≤ x) → ∑ n ∈ Finset.range s.card, (c + ↑n) ≤ ∑ x ∈ s, x"
    },
    {
      "name": "Finset.sum_Ico_add_eq_sum_Ico_add_one",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.LocallyFinite",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} [inst : AddCommMonoid M] {a b : α} [inst_1 : LinearOrder α]\n  [inst_2 : LocallyFiniteOrder α] [inst_3 : AddMonoidWithOne α] [SuccAddOrder α] [NoMaxOrder α],\n  a ≤ b → ∀ (f : α → M), ∑ x ∈ Finset.Ico a b, f x + f b = ∑ x ∈ Finset.Ico a (b + 1), f x"
    },
    {
      "name": "Finset.sum_Ico_eq_sub",
      "module_name": "Mathlib.Algebra.BigOperators.Intervals",
      "kind": "theorem",
      "type": "∀ {δ : Type u_4} [inst : AddCommGroup δ] (f : ℕ → δ) {m n : ℕ},\n  m ≤ n → ∑ k ∈ Finset.Ico m n, f k = ∑ k ∈ Finset.range n, f k - ∑ k ∈ Finset.range m, f k"
    },
    {
      "name": "Finset.sum_range_succ'",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {M : Type u_4} [inst : AddCommMonoid M] (f : ℕ → M) (n : ℕ),\n  ∑ k ∈ Finset.range (n + 1), f k = ∑ k ∈ Finset.range n, f (k + 1) + f 0"
    },
    {
      "name": "Finset.sum_range_eq_add_Ico",
      "module_name": "Mathlib.Algebra.BigOperators.Intervals",
      "kind": "theorem",
      "type": "∀ {M : Type u_3} [inst : AddCommMonoid M] (f : ℕ → M) {n : ℕ},\n  0 < n → ∑ x ∈ Finset.range n, f x = f 0 + ∑ x ∈ Finset.Ico 1 n, f x"
    }
  ]
}
